unsafe fn Mask_calcRunLengthH(
    mut width: c_int,
    mut frame: *mut c_uchar,
    mut runLength: *mut c_int,
) -> c_int {
    let first = unsafe { *frame } as c_int; // SAFETY: caller provides valid pointers for at least one readable frame element.
    let mut head: c_int = if first & 1 != 0 {
        unsafe { *runLength = -1 }; // SAFETY: caller provides valid runLength storage for the written entries.
        1
    } else {
        0
    };

    unsafe { *runLength.add(head as usize) = 1 }; // SAFETY: caller provides valid runLength storage for the written entries.

    let mut prev_bit = first & 1;
    let mut i: c_int = 1;
    while i < width {
        let bit = unsafe { (*frame.add(i as usize) as c_int) & 1 }; // SAFETY: loop invariant ensures 0 <= i < width and caller provides readable frame elements.
        if bit != prev_bit {
            head += 1;
            unsafe { *runLength.add(head as usize) = 1 }; // SAFETY: caller provides valid runLength storage for the written entries.
            prev_bit = bit;
        } else {
            unsafe { *runLength.add(head as usize) += 1 }; // SAFETY: caller provides valid runLength storage for the written entries.
        }
        i += 1;
    }
    head + 1
}

